 III. KOMPONENSEK RÉSZLETES IMPLEMENTÁCIÓJA

 3.1 ZIG: API GATEWAY & CEREBRAS ROUTER

src/gateway/build.zig

zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe = b.addExecutable(.{
        .name = "neural_search_gateway",
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    // Dependencies
    exe.linkLibC();
    exe.linkSystemLibrary("ssl");
    exe.linkSystemLibrary("crypto");

    // HTTP/2 support for Cerebras streaming
    exe.addIncludePath(.{ .path = "/usr/include/nghttp2" });
    exe.linkSystemLibrary("nghttp2");

    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());

    const run_step = b.step("run", "Run the gateway");
    run_step.dependOn(&run_cmd.step);
}


src/gateway/src/main.zig

zig
const std = @import("std");
const http = std.http;
const net = std.net;
const CerebrasClient = @import("cerebras_client.zig").CerebrasClient;
const Router = @import("router.zig").Router;
const DragonflyClient = @import("dragonfly_client.zig").DragonflyClient;

const Config = struct {
    port: u16 = 8080,
    cerebras_api_key: []const u8,
    dragonfly_url: []const u8,
    modal_api_url: []const u8,
    max_concurrent_requests: usize = 10000,
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Load config from environment
    const config = try loadConfig(allocator);
    defer allocator.free(config.cerebras_api_key);
    defer allocator.free(config.dragonfly_url);
    defer allocator.free(config.modal_api_url);

    std.log.info("🚀 Starting Neural Search Gateway on port {d}", .{config.port});

    // Initialize clients
    var cerebras = try CerebrasClient.init(allocator, config.cerebras_api_key);
    defer cerebras.deinit();

    var dragonfly = try DragonflyClient.init(allocator, config.dragonfly_url);
    defer dragonfly.deinit();

    var router = try Router.init(allocator, &cerebras, &dragonfly);
    defer router.deinit();

    // Create server
    const address = try net.Address.parseIp("0.0.0.0", config.port);
    var server = try address.listen(.{
        .reuse_address = true,
        .reuse_port = true,
        .kernel_backlog = 4096,
    });
    defer server.deinit();

    std.log.info("✅ Gateway listening on {}", .{address});

    // Accept loop (concurrent connections)
    var thread_pool: std.Thread.Pool = undefined;
    try thread_pool.init(.{
        .allocator = allocator,
        .n_jobs = config.max_concurrent_requests,
    });
    defer thread_pool.deinit();

    while (true) {
        const conn = try server.accept();

        // Spawn handler in thread pool
        try thread_pool.spawn(handleConnection, .{
            allocator,
            conn,
            &router,
        });
    }
}

fn handleConnection(
    allocator: std.mem.Allocator,
    conn: net.Server.Connection,
    router: *Router,
) void {
    defer conn.stream.close();

    handleRequest(allocator, conn, router) catch |err| {
        std.log.err("Request handling error: {}", .{err});
    };
}

fn handleRequest(
    allocator: std.mem.Allocator,
    conn: net.Server.Connection,
    router: *Router,
) !void {
    // Parse HTTP request (zero-copy where possible)
    var read_buffer: u8 = undefined;
    const bytes_read = try conn.stream.read(&read_buffer);

    const request = try parseHttpRequest(allocator, read_buffer[0..bytes_read]);
    defer request.deinit(allocator);

    // Route based on path
    if (std.mem.eql(u8, request.path, "/search")) {
        try handleSearch(allocator, conn, router, request);
    } else if (std.mem.eql(u8, request.path, "/health")) {
        try handleHealth(conn);
    } else {
        try send404(conn);
    }
}

fn handleSearch(
    allocator: std.mem.Allocator,
    conn: net.Server.Connection,
    router: *Router,
    request: HttpRequest,
) !void {
    const start_time = std.time.nanoTimestamp();

    // Parse JSON body
    const body = try std.json.parseFromSlice(
        SearchRequest,
        allocator,
        request.body,
        .{},
    );
    defer body.deinit();

    const search_req = body.value;

    // 1. Check Dragonfly cache
    const cache_key = try std.fmt.allocPrint(
        allocator,
        "query:{s}",
        .{search_req.query},
    );
    defer allocator.free(cache_key);

    if (try router.dragonfly.get(cache_key)) |cached_response| {
        defer allocator.free(cached_response);
        std.log.info("✅ Cache hit: {s}", .{search_req.query});
        try sendJsonResponse(conn, 200, cached_response);
        return;
    }

    // 2. Route to appropriate Cerebras model
    const model_tier = router.determineModelTier(search_req);

    // 3. Query Modal.com vector search (async)
    const vector_results = try queryModalVectorSearch(
        allocator,
        router.modal_url,
        search_req.query,
    );
    defer vector_results.deinit(allocator);

    // 4. Build RAG context
    const rag_context = try buildRagContext(allocator, vector_results);
    defer allocator.free(rag_context);

    // 5. Stream from Cerebras
    const cerebras_prompt = try std.fmt.allocPrint(
        allocator,
        "Context:\n{s}\n\nQuestion: {s}\n\nAnswer:",
        .{ rag_context, search_req.query },
    );
    defer allocator.free(cerebras_prompt);

    // Send SSE headers
    try sendSseHeaders(conn);

    // Stream Cerebras response
    var stream = try router.cerebras.streamCompletion(
        model_tier,
        cerebras_prompt,
    );
    defer stream.deinit();

    var full_response = std.ArrayList(u8).init(allocator);
    defer full_response.deinit();

    while (try stream.next()) |token| {
        // Send to client immediately (Server-Sent Events)
        try sendSseEvent(conn, token);

        // Accumulate for caching
        try full_response.appendSlice(token);
    }

    // Cache response in Dragonfly
    try router.dragonfly.set(
        cache_key,
        full_response.items,
        3600, // 1 hour TTL
    );

    const duration_ms = @as(f64, @floatFromInt(std.time.nanoTimestamp() - start_time)) / 1_000_000.0;
    std.log.info("✅ Search completed: {s} ({d:.2}ms)", .{ search_req.query, duration_ms });
}

const SearchRequest = struct {
    query: []const u8,
    num_results: usize = 10,
    deep_research: bool = false,
};

const HttpRequest = struct {
    method: []const u8,
    path: []const u8,
    headers: std.StringHashMap([]const u8),
    body: []const u8,

    fn deinit(self: *HttpRequest, allocator: std.mem.Allocator) void {
        self.headers.deinit();
        allocator.free(self.method);
        allocator.free(self.path);
        allocator.free(self.body);
    }
};

fn parseHttpRequest(allocator: std.mem.Allocator, data: []const u8) !HttpRequest {
    // Simple HTTP parser (production: use proper HTTP library)
    var lines = std.mem.splitScalar(u8, data, '\n');

    const request_line = lines.next() orelse return error.InvalidRequest;
    var request_parts = std.mem.splitScalar(u8, request_line, ' ');

    const method = try allocator.dupe(u8, request_parts.next() orelse return error.InvalidMethod);
    const path = try allocator.dupe(u8, request_parts.next() orelse return error.InvalidPath);

    var headers = std.StringHashMap([]const u8).init(allocator);

    // Parse headers
    while (lines.next()) |line| {
        if (line.len == 0 or line == '\r') break;

        const colon_pos = std.mem.indexOfScalar(u8, line, ':') orelse continue;
        const key = std.mem.trim(u8, line[0..colon_pos], " \r");
        const value = std.mem.trim(u8, line[colon_pos + 1 ..], " \r");

        try headers.put(key, value);
    }

    // Rest is body
    const body_start = std.mem.indexOf(u8, data, "\r\n\r\n") orelse data.len;
    const body = if (body_start + 4 < data.len)
        try allocator.dupe(u8, data[body_start + 4 ..])
    else
        try allocator.dupe(u8, "");

    return HttpRequest{
        .method = method,
        .path = path,
        .headers = headers,
        .body = body,
    };
}

fn loadConfig(allocator: std.mem.Allocator) !Config {
    return Config{
        .cerebras_api_key = try std.process.getEnvVarOwned(allocator, "CEREBRAS_API_KEY"),
        .dragonfly_url = try std.process.getEnvVarOwned(allocator, "DRAGONFLY_URL"),
        .modal_api_url = try std.process.getEnvVarOwned(allocator, "MODAL_API_URL"),
    };
}

fn queryModalVectorSearch(
    allocator: std.mem.Allocator,
    modal_url: []const u8,
    query: []const u8,
) !VectorSearchResults {
    // HTTP call to Modal.com function (implementation details)
    _ = allocator;
    _ = modal_url;
    _ = query;
    return VectorSearchResults{};
}

fn buildRagContext(allocator: std.mem.Allocator, results: VectorSearchResults) ![]const u8 {
    _ = results;
    return try allocator.dupe(u8, "RAG context placeholder");
}

fn sendSseHeaders(conn: net.Server.Connection) !void {
    const headers =
        \\HTTP/1.1 200 OK
        \\Content-Type: text/event-stream
        \\Cache-Control: no-cache
        \\Connection: keep-alive
        \\
        \\
    ;
    _ = try conn.stream.write(headers);
}

fn sendSseEvent(conn: net.Server.Connection, data: []const u8) !void {
    var buffer: u8 = undefined;
    const event = try std.fmt.bufPrint(&buffer, "data: {s}\n\n", .{data});
    _ = try conn.stream.write(event);
}

fn sendJsonResponse(conn: net.Server.Connection, status: u16, body: []const u8) !void {
    var buffer: u8 = undefined;
    const headers = try std.fmt.bufPrint(
        &buffer,
        "HTTP/1.1 {d} OK\r\nContent-Type: application/json\r\nContent-Length: {d}\r\n\r\n",
        .{ status, body.len },
    );
    _ = try conn.stream.write(headers);
    _ = try conn.stream.write(body);
}

fn handleHealth(conn: net.Server.Connection) !void {
    const response = "{\"status\":\"healthy\"}";
    try sendJsonResponse(conn, 200, response);
}

fn send404(conn: net.Server.Connection) !void {
    const response = "{\"error\":\"Not Found\"}";
    try sendJsonResponse(conn, 404, response);
}

const VectorSearchResults = struct {
    fn deinit(self: *VectorSearchResults, allocator: std.mem.Allocator) void {
        _ = self;
        _ = allocator;
    }
};


src/gateway/src/cerebras_client.zig

zig
const std = @import("std");
const http = std.http;

pub const ModelTier = enum {
    Speed,    // Qwen 235B - 1400-1500 t/s
    Balanced, // GPT-OSS 120B - 2500-3500 t/s
    Smart,    // GLM 4.7 - 300-1000 t/s (SOTA reasoning)
};

pub const CerebrasClient = struct {
    allocator: std.mem.Allocator,
    api_key: []const u8,
    base_url: []const u8 = "https://api.cerebras.ai/v1",
    http_client: http.Client,

    pub fn init(allocator: std.mem.Allocator, api_key: []const u8) !CerebrasClient {
        return CerebrasClient{
            .allocator = allocator,
            .api_key = api_key,
            .http_client = http.Client{ .allocator = allocator },
        };
    }

    pub fn deinit(self: *CerebrasClient) void {
        self.http_client.deinit();
    }

    pub fn streamCompletion(
        self: *CerebrasClient,
        model_tier: ModelTier,
        prompt: []const u8,
    ) !CompletionStream {
        const model_id = switch (model_tier) {
            .Speed => "qwen-3-235b-a22b-instruct-2507", // 1400+ t/s
            .Balanced => "gpt-oss-120b",
            .Smart => "qwen-3-235b-a22b-thinking-2507", // SOTA 1700 t/s
        };

        // Build request JSON
        const request_body = try std.fmt.allocPrint(
            self.allocator,
            \\{{"model":"{s}","messages":[{{"role":"user","content":"{s}"}}],"stream":true,"max_tokens":4000}}
            ,
            .{ model_id, prompt },
        );
        defer self.allocator.free(request_body);

        // Create HTTP request
        const uri = try std.Uri.parse(try std.fmt.allocPrint(
            self.allocator,
            "{s}/chat/completions",
            .{self.base_url},
        ));

        var headers = http.Headers.init(self.allocator);
        defer headers.deinit();

        try headers.append("Authorization", try std.fmt.allocPrint(
            self.allocator,
            "Bearer {s}",
            .{self.api_key},
        ));
        try headers.append("Content-Type", "application/json");

        var req = try self.http_client.request(.POST, uri, headers, .{});
        defer req.deinit();

        try req.writer().writeAll(request_body);
        try req.finish();

        return CompletionStream{
            .allocator = self.allocator,
            .response = req,
        };
    }
};

pub const CompletionStream = struct {
    allocator: std.mem.Allocator,
    response: http.Client.Request,
    buffer: u8 = undefined,
    buffer_pos: usize = 0,

    pub fn deinit(self: *CompletionStream) void {
        self.response.deinit();
    }

