const std = @import("std");
const net = std.net;

pub const DragonflyClient = struct {
    allocator: std.mem.Allocator,
    conn: net.Stream,
    url: []const u8,

    pub fn init(allocator: std.mem.Allocator, url: []const u8) !DragonflyClient {
        // Parse Dragonfly URL
        // Connect via TCP
        const address = try net.Address.parseIp("127.0.0.1", 6379); // Placeholder
        const stream = try net.tcpConnectToAddress(address);

        return DragonflyClient{
            .allocator = allocator,
            .conn = stream,
            .url = url,
        };
    }

    pub fn deinit(self: *DragonflyClient) void {
        self.conn.close();
    }

    pub fn get(self: *DragonflyClient, key: []const u8) !?[]const u8 {
        // RESP3 protocol: *2\r\n$3\r\nGET\r\n$<keylen>\r\n<key>\r\n
        var cmd = std.ArrayList(u8).init(self.allocator);
        defer cmd.deinit();

        try cmd.writer().print("*2\r\n$3\r\nGET\r\n${d}\r\n{s}\r\n", .{ key.len, key });

        _ = try self.conn.write(cmd.items);

        // Read response
        var response_buffer: u8 = undefined;
        const bytes_read = try self.conn.read(&response_buffer);

        // Parse RESP3 response
        if (response_buffer == '$') {
            // Bulk string: $<len>\r\n<data>\r\n
            return try self.allocator.dupe(u8, response_buffer[0..bytes_read]);
        } else if (response_buffer == '_') {
            // Null
            return null;
        }

        return error.InvalidResponse;
    }

    pub fn set(self: *DragonflyClient, key: []const u8, value: []const u8, ttl_seconds: u64) !void {
        // SET key value EX ttl
        var cmd = std.ArrayList(u8).init(self.allocator);
        defer cmd.deinit();

        try cmd.writer().print(
            "*4\r\n$3\r\nSET\r\n${d}\r\n{s}\r\n${d}\r\n{s}\r\n$2\r\nEX\r\n${d}\r\n{d}\r\n",
            .{ key.len, key, value.len, value, @as(usize, @intCast(ttl_seconds)), ttl_seconds },
        );

        _ = try self.conn.write(cmd.items);

        // Read OK response
        var response: u8 = undefined;[1]
        _ = try self.conn.read(&response);
    }

    pub fn pipeline(self: *DragonflyClient) !Pipeline {
        return Pipeline{
            .client = self,
            .commands = std.ArrayList([]const u8).init(self.allocator),
        };
    }
};

pub const Pipeline = struct {
    client: *DragonflyClient,
    commands: std.ArrayList([]const u8),

    pub fn sadd(self: *Pipeline, key: []const u8, member: []const u8) !void {
        const cmd = try std.fmt.allocPrint(
            self.client.allocator,
            "*3\r\n$4\r\nSADD\r\n${d}\r\n{s}\r\n${d}\r\n{s}\r\n",
            .{ key.len, key, member.len, member },
        );
        try self.commands.append(cmd);
    }

    pub fn lpush(self: *Pipeline, key: []const u8, value: []const u8) !void {
        const cmd = try std.fmt.allocPrint(
            self.client.allocator,
            "*3\r\n$5\r\nLPUSH\r\n${d}\r\n{s}\r\n${d}\r\n{s}\r\n",
            .{ key.len, key, value.len, value },
        );
        try self.commands.append(cmd);
    }

    pub fn execute(self: *Pipeline) !void {
        // Send all commands at once
        for (self.commands.items) |cmd| {
            _ = try self.client.conn.write(cmd);
        }

        // Read all responses (discard for now)
        var response: u8 = undefined;
        for (0..self.commands.items.len) |_| {
            _ = try self.client.conn.read(&response);
        }

        // Cleanup
        for (self.commands.items) |cmd| {
            self.client.allocator.free(cmd);
        }
        self.commands.deinit();
    }
};




