class pub UrlFrontier {
  let @client: TcpClient
  let @dragonfly_url: String

  fn pub static new(dragonfly_url: String) -> UrlFrontier {
    let client = TcpClient.new(parse_host(dragonfly_url), parse_port(dragonfly_url))

    UrlFrontier { @client = client, @dragonfly_url = dragonfly_url }
  }

  fn pub async add_urls(urls: Array[String]) {
    # Dragonfly pipeline: 25x faster than Redis
    let pipeline = @client.pipeline

    urls.each fn (url) {
      # Add to queue
      pipeline.lpush('frontier:queue', url)

      # Track domain
      let domain = extract_domain(url)
      pipeline.sadd('frontier:domains', domain)

      # Rate limit tracking
      pipeline.hset('frontier:rate_limit', domain, DateTime.now.to_string)
    }

    pipeline.execute
  }

  fn pub async pop_url -> Option[String] {
    # Respect rate limits (politeness policy)
    let url = @client.rpop('frontier:queue')

    match url {
      case Some(u) -> {
        let domain = extract_domain(u)

        # Check rate limit
        let last_crawl = @client.hget('frontier:rate_limit', domain)

        match last_crawl {
          case Some(timestamp) -> {
            let elapsed = DateTime.now.timestamp - parse_timestamp(timestamp)

            if elapsed < 1.0 {
              # Re-queue for later
              @client.lpush('frontier:queue', u)
              return Option.None
            }
          }
          case None -> {}
        }

        # Update rate limit
        @client.hset('frontier:rate_limit', domain, DateTime.now.to_string)

        Option.Some(u)
      }
      case None -> Option.None
    }
  }

  fn pub async size -> Int {
    @client.llen('frontier:queue').or(0)
  }
}

