import std.net.http (HttpClient, HttpRequest)
import std.time (Duration)

class pub Fetcher {
  let @client: HttpClient
  let @timeout: Duration
  let @max_retries: Int

  fn pub static new -> Fetcher {
    Fetcher {
      @client = HttpClient.new,
      @timeout = Duration.from_secs(30),
      @max_retries = 3
    }
  }

  fn pub async fetch(url: String) -> Result[String, String] {
    let mut retries = 0

    loop {
      let request = HttpRequest.new(
        method: 'GET',
        url: url,
        headers: {
          'User-Agent': 'NeuralSearchBot/1.0 (+https://neuralsearch.ai/bot)',
          'Accept': 'text/html,application/xhtml+xml',
          'Accept-Encoding': 'gzip, deflate'
        },
        timeout: @timeout
      )

      match @client.send(request) {
        case Ok(response) -> {
          if response.status_code == 200 {
            return Result.Ok(response.body)
          } else if response.status_code >= 500 {
            # Retry on server errors
            retries += 1
            if retries >= @max_retries {
              return Result.Error('Max retries exceeded')
            }
            continue
          } else {
            return Result.Error('HTTP {response.status_code}')
          }
        }
        case Error(e) -> {
          retries += 1
          if retries >= @max_retries {
            return Result.Error(e.to_string)
          }
          continue
        }
      }
    }
  }
}


