-- Advanced similarity metrics for neural search

-- Euclidean distance (L2)
def euclidean [n] (a: [n]f32) (b: [n]f32) : f32 =
  map2 (\x y -> (x - y) * (x - y)) a b
  |> reduce (+) 0f32
  |> f32.sqrt

-- Manhattan distance (L1)
def manhattan [n] (a: [n]f32) (b: [n]f32) : f32 =
  map2 (\x y -> f32.abs (x - y)) a b
  |> reduce (+) 0f32

-- Dot product (unnormalized)
def dot_product [n] (a: [n]f32) (b: [n]f32) : f32 =
  map2 (*) a b |> reduce (+) 0f32

-- Jaccard similarity (for sparse vectors)
def jaccard [n] (a: [n]f32) (b: [n]f32) : f32 =
  let intersection = map2 (\x y -> f32.min x y) a b |> reduce (+) 0f32
  let union = map2 (\x y -> f32.max x y) a b |> reduce (+) 0f32
  in intersection / union

-- Angular distance (related to cosine)
def angular_distance [n] (a: [n]f32) (b: [n]f32) : f32 =
  let cos_sim = cosine_similarity a b
  in f32.acos cos_sim / f32.pi

-- Batch pairwise similarities (N x M matrix)
entry pairwise_cosine [n][m][d] (queries: [n][d]f32) 
                                 (docs: [m][d]f32) : [n][m]f32 =
  map (\q -> map (cosine_similarity q) docs) queries

-- KNN graph construction (for HNSW)
entry build_knn_graph [m][n] (embeddings: [m][n]f32) (k: i64) : [m][k]i64 =
  let distances = pairwise_cosine embeddings embeddings
  in map (\dists ->
    let indices = argsort dists |> reverse
    in take (k+1) indices |> drop 1  -- Exclude self
  ) distances


