-- Index construction optimized for B200 GPUs

-- K-means clustering for IVF index
def kmeans [m][n] (data: [m][n]f32) (k: i64) (max_iter: i64) : [k][n]f32 =
  -- Initialize centroids (k-means++)
  let initial_centroids = kmeans_pp_init data k

  -- Iterative refinement
  let (final_centroids, _) = loop (centroids, iter) = (initial_centroids, 0)
    while iter < max_iter do
    -- Assignment step (parallel)
    let assignments = map (\point ->
      let dists = map (euclidean point) centroids
      in argmin dists
    ) data

    -- Update step (parallel)
    let new_centroids = map (\c_idx ->
      let cluster_points = filter (\(i, _) -> assignments[i] == c_idx) 
                                  (zip (iota m) data)
                          |> map (.1)
      let cluster_size = length cluster_points
      in if cluster_size == 0
         then centroids[c_idx]  -- Keep old centroid
         else map (\dim -> (map (.[dim]) cluster_points |> reduce (+) 0f32) / f32.i64 cluster_size)
                  (iota n)
    ) (iota k)

    in (new_centroids, iter + 1)

  in final_centroids

def kmeans_pp_init [m][n] (data: [m][n]f32) (k: i64) : [k][n]f32 =
