-- Simplified Transformer attention (single head)
def attention [s][d] (query: [s][d]f32) 
                      (key: [s][d]f32) 
                      (value: [s][d]f32) : [s][d]f32 =
  let d_k = f32.i64 d
  let scores = pairwise_dot query key |> map (map (/ f32.sqrt d_k))
  let attention_weights = map softmax scores
  in map (\weights ->
    map (\dim ->
      map2 (\w v -> w * v[dim]) weights value |> reduce (+) 0f32
    ) (iota d)
  ) attention_weights

def pairwise_dot [n][m][d] (a: [n][d]f32) (b: [m][d]f32) : [n][m]f32 =
  map (\a_vec ->
    map (\b_vec -> dot_product a_vec b_vec) b
  ) a

def softmax [n] (xs: [n]f32) : [n]f32 =
  let max_x = reduce f32.max (f32.lowest) xs
  let exps = map (\x -> f32.exp (x - max_x)) xs
  let sum_exps = reduce (+) 0f32 exps
  in map (/ sum_exps) exps

-- Multi-head attention
def multihead_attention [s][d][h] (query: [s][d]f32)
                                    (key: [s][d]f32)
                                    (value: [s][d]f32)
                                    (W_Q: [h][d][d/h]f32)
                                    (W_K: [h][d][d/h]f32)
                                    (W_V: [h][d][d/h]f32)
                                    (W_O: [d][d]f32) : [s][d]f32 =
  let d_head = d / h

  -- Project to multiple heads
  let heads = map (\head_idx ->
    let Q = map (\q -> matmul q W_Q[head_idx]) query
    let K = map (\k -> matmul k W_K[head_idx]) key
    let V = map (\v -> matmul v W_V[head_idx]) value
    in attention Q K V
  ) (iota h)

  -- Concatenate heads
  let concat = map (\seq_idx ->
    map (\head -> heads[head][seq_idx]) (iota h) |> flatten
  ) (iota s)

  -- Output projection
  in map (\vec -> matmul vec W_O) concat

def matmul [n][m] (vec: [n]f32) (mat: [n][m]f32) : [m]f32 =
  map (\col_idx ->
    map (\row_idx -> vec[row_idx] * mat[row_idx][col_idx]) (iota n)
    |> reduce (+) 0f32
  ) (iota m)

