# Bend - Massively Parallel PageRank on GPU
# Runs on HVM2 runtime with automatic parallelization

# Graph represented as adjacency list
type Graph = Map U32 [U32]

# PageRank algorithm (parallel iteration)
def pagerank(graph: Graph, num_iters: U32, damping: F32) -> Map U32 F32:
  num_nodes = len(graph)

  # Initialize scores
  scores = {node: 1.0 / num_nodes for node in graph.keys()}

  # Iterative update (Bend automatically parallelizes this)
  for _ in range(num_iters):
    new_scores = {}

    # Parallel map over all nodes
    for node in graph.keys():
      # Sum contributions from incoming links
      contrib_sum = sum([
        scores[source] / len(graph[source])
        for source in graph.keys()
        if node in graph[source]
      ])

      # Damping formula
      new_scores[node] = (1.0 - damping) / num_nodes + damping * contrib_sum

    scores = new_scores

  return scores

# Parallel PageRank with sparse matrix multiplication
def pagerank_sparse(adjacency: [[F32]], num_iters: U32, damping: F32) -> [F32]:
  n = len(adjacency)

  # Initialize
  scores = [1.0 / n] * n

  # Power iteration (parallelized by Bend/HVM2)
  for _ in range(num_iters):
    new_scores = [0.0] * n

    # Matrix-vector multiplication (parallel)
    for i in range(n):
      for j in range(n):
        new_scores[i] += adjacency[j][i] * scores[j]

      # Apply damping
      new_scores[i] = (1.0 - damping) / n + damping * new_scores[i]

    scores = new_scores

  return scores

# Personalized PageRank (topic-sensitive)
def personalized_pagerank(
  graph: Graph,
  seed_nodes: [U32],
  teleport_prob: F32,
  num_iters: U32
) -> Map U32 F32:
  num_nodes = len(graph)
  num_seeds = len(seed_nodes)

  # Initialize with seed nodes
  scores = {
    node: 1.0 / num_seeds if node in seed_nodes else 0.0
    for node in graph.keys()
  }

  for _ in range(num_iters):
    new_scores = {}

    for node in graph.keys():
      # Random walk contribution
      walk_contrib = sum([
        scores[source] / len(graph[source])
        for source in graph.keys()
        if node in graph[source]
      ])

      # Teleport contribution (back to seed nodes)
      teleport_contrib = (
        1.0 / num_seeds if node in seed_nodes else 0.0
      )

      new_scores[node] = (
        (1.0 - teleport_prob) * walk_contrib +
        teleport_prob * teleport_contrib
      )

    scores = new_scores

  return scores

# HITS algorithm (Hubs and Authorities)
def hits(graph: Graph, num_iters: U32) -> (Map U32 F32, Map U32 F32):
  # Initialize
  hubs = {node: 1.0 for node in graph.keys()}
  authorities = {node: 1.0 for node in graph.keys()}

  for _ in range(num_iters):
    # Update authorities (parallel)
    new_auth = {}
    for node in graph.keys():
      new_auth[node] = sum([
        hubs[source]
        for source in graph.keys()
        if node in graph[source]
      ])

    # Normalize
    norm = sqrt(sum([a*a for a in new_auth.values()]))
    authorities = {k: v/norm for k, v in new_auth.items()}

    # Update hubs (parallel)
    new_hubs = {}
    for node in graph.keys():
      new_hubs[node] = sum([
        authorities[target]
        for target in graph[node]
      ])

    # Normalize
    norm = sqrt(sum([h*h for h in new_hubs.values()]))
    hubs = {k: v/norm for k, v in new_hubs.items()}

  return (hubs, authorities)

# Parallel BFS (Breadth-First Search)
def parallel_bfs(graph: Graph, start: U32) -> Map U32 U32:
  distances = {node: U32::MAX for node in graph.keys()}
  distances[start] = 0

  frontier = [start]
  level = 0

  # Parallel expansion of frontier
  while len(frontier) > 0:
    level += 1

    # Next frontier (parallel map)
    next_frontier = flatten([
      [neighbor for neighbor in graph[node] if distances[neighbor] == U32::MAX]
      for node in frontier
    ])

    # Update distances (parallel)
    for node in next_frontier:
      distances[node] = level

    frontier = next_frontier

  return distances

# Connected components (parallel union-find)
def connected_components(graph: Graph) -> Map U32 U32:
  # Initialize: each node is its own component
  parent = {node: node for node in graph.keys()}

  # Parallel edge contraction
  changed = True
  while changed:
    changed = False

    # Parallel over all edges
    for node in graph.keys():
      for neighbor in graph[node]:
        p1 = find(parent, node)
        p2 = find(parent, neighbor)

        if p1 != p2:
          # Union
          parent[max(p1, p2)] = min(p1, p2)
          changed = True

  # Path compression
  return {node: find(parent, node) for node in graph.keys()}

def find(parent: Map U32 U32, node: U32) -> U32:
  if parent[node] == node:
    return node
  else:
    root = find(parent, parent[node])
    parent[node] = root  # Path compression
    return root

# Helper: flatten nested lists
def flatten(lists: [[T]]) -> [T]:
  fold (++) [] lists


