# SimRank: similarity based on graph structure
def simrank(graph: Graph, num_iters: U32, decay: F32) -> [[F32]]:
  n = len(graph)
  nodes = list(graph.keys())

  # Initialize similarity matrix
  sim = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]

  for _ in range(num_iters):
    new_sim = [[0.0] * n for _ in range(n)]

    # Parallel computation of similarities
    for i in range(n):
      for j in range(n):
        if i == j:
          new_sim[i][j] = 1.0
        else:
          # Incoming neighbors
          in_i = [k for k in range(n) if nodes[j] in graph[nodes[k]]]
          in_j = [k for k in range(n) if nodes[j] in graph[nodes[k]]]

          if len(in_i) == 0 or len(in_j) == 0:
            new_sim[i][j] = 0.0
          else:
            new_sim[i][j] = (decay / (len(in_i) * len(in_j))) * sum([
              sim[a][b]
              for a in in_i
              for b in in_j
            ])

    sim = new_sim

  return sim

