# Katz centrality: considers all paths
def katz_centrality(adjacency: [[F32]], alpha: F32, beta: F32) -> [F32]:
  n = len(adjacency)

  # Katz = (I - alpha*A^T)^(-1) * beta * 1
  # Approximated by power series: sum(alpha^k * A^k * 1)

  centrality = [beta] * n
  A_k = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]

  for k in range(20):  # Approximate with 20 terms
    # A_k = A^k
    A_k = matrix_mult(adjacency, A_k)

    # Add alpha^k * A^k * 1 to centrality
    for i in range(n):
      centrality[i] += pow(alpha, k+1) * sum(A_k[i])

  return centrality

def matrix_mult(A: [[F32]], B: [[F32]]) -> [[F32]]:
  n = len(A)
  m = len(B)
  k = len(B)

  return [[
    sum([A[i][j] * B[j][k] for j in range(k)])
    for k in range(m)
  ] for i in range(n)]

