# Community detection (Louvain method - simplified)
def louvain_communities(graph: Graph) -> Map U32 U32:
  # Phase 1: Greedy optimization of modularity
  communities = {node: node for node in graph.keys()}  # Each node starts in own community

  improved = True
  while improved:
    improved = False

    # Parallel over nodes
    for node in graph.keys():
      # Try moving to neighbor's community
      best_comm = communities[node]
      best_modularity = compute_modularity(graph, communities)

      for neighbor in graph[node]:
        neighbor_comm = communities[neighbor]

        # Test move
        communities[node] = neighbor_comm
        new_modularity = compute_modularity(graph, communities)

        if new_modularity > best_modularity:
          best_comm = neighbor_comm
          best_modularity = new_modularity

        # Revert
        communities[node] = communities[node]

      if best_comm != communities[node]:
        communities[node] = best_comm
        improved = True

  return communities

def compute_modularity(graph: Graph, communities: Map U32 U32) -> F32:
  m = sum([len(edges) for edges in graph.values()]) / 2.0  # Total edges

  Q = 0.0
  for node1 in graph.keys():
    for node2 in graph[node1]:
      if communities[node1] == communities[node2]:
        k1 = len(graph[node1])
        k2 = len(graph[node2])
        Q += 1.0 - (k1 * k2) / (2.0 * m)

  return Q / (2.0 * m)


