# Domain-based clustering for search ranking

type Domain = String
type DomainGraph = Map Domain [Domain]

# Domain authority clustering
def cluster_domains_by_authority(
  domain_graph: DomainGraph,
  num_clusters: U32
) -> Map Domain U32:
  # Compute PageRank for domains
  pagerank_scores = pagerank(domain_graph, 20, 0.85)

  # K-means clustering on PageRank scores
  clusters = kmeans_1d(
    list(pagerank_scores.values()),
    num_clusters
  )

  return {
    domain: clusters[i]
    for i, domain in enumerate(domain_graph.keys())
  }

def kmeans_1d(values: [F32], k: U32) -> [U32]:
  # 1D K-means (fast, parallel)
  sorted_values = sorted(enumerate(values), key=lambda x: x[4])

  # Split into k equal-sized groups
  cluster_size = len(values) / k

  assignments =  * len(values)
  for i, (orig_idx, _) in enumerate(sorted_values):
    assignments[orig_idx] = U32(i / cluster_size)

  return assignments

# Topic-based domain clustering
def cluster_domains_by_topic(
  domain_embeddings: Map Domain [F32],
  num_topics: U32
) -> Map Domain U32:
  # K-means on domain embeddings
  domains = list(domain_embeddings.keys())
  embeddings = [domain_embeddings[d] for d in domains]

  clusters = kmeans(embeddings, num_topics, max_iters=50)

  return {domains[i]: clusters[i] for i in range(len(domains))}

def kmeans(data: [[F32]], k: U32, max_iters: U32) -> [U32]:
  # Multi-dimensional K-means (parallel)
  n = len(data)
  d = len(data)

  # Initialize centroids (k-means++)
  centroids = init_centroids(data, k)

  assignments =  * n

  for _ in range(max_iters):
    # Assignment step (parallel)
    for i in range(n):
      distances = [euclidean_dist(data[i], c) for c in centroids]
      assignments[i] = argmin(distances)

    # Update step (parallel)
    for c in range(k):
      cluster_points = [data[i] for i in range(n) if assignments[i] == c]

      if len(cluster_points) > 0:
        centroids[c] = [
          sum([p[dim] for p in cluster_points]) / len(cluster_points)
          for dim in range(d)
        ]

  return assignments

def euclidean_dist(a: [F32], b: [F32]) -> F32:
  return sqrt(sum([(a[i] - b[i]) ** 2 for i in range(len(a))]))

def argmin(values: [F32]) -> U32:
  min_val = min(values)
  return values.index(min_val)

def init_centroids(data: [[F32]], k: U32) -> [[F32]]:
  # K-means++ initialization
  centroids = [data]  # First centroid: random (simplified)

  for _ in range(k - 1):
    # Distance to nearest centroid
    distances = [
      min([euclidean_dist(point, c) for c in centroids])
      for point in data
    ]

    # Choose farthest point
    farthest_idx = argmax(distances)
    centroids.append(data[farthest_idx])

  return centroids

def argmax(values: [F32]) -> U32:
  max_val = max(values)
  return values.index(max_val)


